      const saved=await response.json();const[billData,orderData,summary]=await Promise.all([apiFetch(`${API}/supplier-bills`).then(r=>r.json()),apiFetch(`${API}/purchase-orders`).then(r=>r.json()),apiFetch(`${API}/dashboard/summary`).then(r=>r.json())]);setSupplierBills(billData);setPurchaseOrders(orderData);setMetrics(summary);setBillingOrder(null);setBillKey('');notify(`${saved.billNumber} recorded · ${formatCurrency(saved.total)} payable`);
