      const saved=await response.json();const[billData,summary]=await Promise.all([apiFetch(`${API}/supplier-bills`).then(r=>r.json()),apiFetch(`${API}/dashboard/summary`).then(r=>r.json())]);setSupplierBills(billData);setMetrics(summary);setPayingBill(null);setBillPaymentKey('');notify(`Supplier payment recorded · ${formatCurrency(saved.amountPaid)} paid`);
